<template>
  <div class="performance">
    <el-card>
      <div slot="header">
        <span>履约任务管理</span>
      </div>
      <el-table :data="tasks" style="width: 100%">
        <el-table-column prop="contractName" label="合同名称"></el-table-column>
        <el-table-column prop="taskName" label="任务名称"></el-table-column>
        <el-table-column prop="amount" label="金额">
          <template slot-scope="scope">¥{{ Number(scope.row.amount).toLocaleString() }}</template>
        </el-table-column>
        <el-table-column prop="dueDate" label="到期日期"></el-table-column>
        <el-table-column prop="owner" label="负责人"></el-table-column>
        <el-table-column prop="status" label="状态">
          <template slot-scope="scope">
            <el-tag :type="getTaskStatusType(scope.row.status)">{{ getTaskStatusText(scope.row.status) }}</el-tag>
          </template>
        </el-table-column>
        <el-table-column label="操作" width="100">
          <template slot-scope="scope">
            <el-button size="mini" type="primary" v-if="scope.row.status === 'PENDING'" @click="completeTask(scope.row.id)">完成</el-button>
          </template>
        </el-table-column>
      </el-table>
    </el-card>
  </div>
</template>

<script>
import api from '../api'

export default {
  name: 'Performance',
  data() {
    return {
      tasks: []
    }
  },
  mounted() {
    this.loadTasks()
  },
  methods: {
    async loadTasks() {
      try {
        const res = await api.getTasks()
        this.tasks = res.data
      } catch (e) {
        this.$message.error('加载失败')
      }
    },
    async completeTask(taskId) {
      try {
        await api.completeTask(taskId)
        this.$message.success('任务已完成')
        this.loadTasks()
      } catch (e) {
        this.$message.error('操作失败')
      }
    },
    getTaskStatusText(status) {
      const map = {
        PENDING: '待处理',
        IN_PROGRESS: '进行中',
        COMPLETED: '已完成',
        EXPIRED: '已逾期'
      }
      return map[status] || status
    },
    getTaskStatusType(status) {
      if (status === 'COMPLETED') return 'success'
      if (status === 'EXPIRED') return 'danger'
      if (status === 'IN_PROGRESS') return 'warning'
      return 'info'
    }
  }
}
</script>
